fetch(`${API_BASE}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: formData.email,
        password: formData.password
      })
    })
      .then(res => res.json().then(data => ({ status: res.status, data })))
      .then(({ status, data }) => {
        setLoading(false);
        if (status === 200) {
          persistProfileFromUser(data.user);

          localStorage.setItem('isLoggedIn', 'true');
          localStorage.setItem('userEmail', formData.email);
          localStorage.setItem('loginMethod', 'local');
          if (data.token) localStorage.setItem('authToken', data.token);

          if (rememberMe) {
            localStorage.setItem(REMEMBER_EMAIL_KEY, formData.email.trim().toLowerCase());
          } else {
            localStorage.removeItem(REMEMBER_EMAIL_KEY);
          }

          dispatchAuthChanged();
          navigate('/');
        } else {
          setValidFields(prev => ({ ...prev, password: false }));
          setErrors(prev => ({ ...prev, password: true }));

          const errorSpan = document.getElementById('error-password');
          if (errorSpan) {
            errorSpan.textContent = data.message || "Tài khoản hoặc mật khẩu không chính xác.";
          }

          triggerShake('password');
        }
      })
      .catch

